/** Standalone bootstrap helper; generated into the root installer, never loaded anonymously. */
final class C1zzAiArchiveInstaller
{
    const PREFIX = 'GXModules/c1zz/c1zzki/';
    const LEGACY_PREFIX = 'GXModules/c1zz/BlogAI/';
    private $root;
    private $package;
    private $embedded;

    public function __construct($root, array $package, $embedded = null)
    {
        $this->root = realpath($root);
        $this->package = $package;
        $this->embedded = $embedded;
        if (!$this->root || !isset($package['version'], $package['archive'], $package['archive_sha256'], $package['files'])
            || !is_string($package['version']) || !preg_match('/\A\d+\.\d+\.\d+\z/', $package['version'])
            || (isset($package['installer']) && $package['installer'] !== 'c1zz-ai-install-'.$package['version'].'.php')
            || $package['archive'] !== 'c1zz-ai-' . $package['version'] . '.zip'
            || !is_string($package['archive_sha256']) || !preg_match('/\A[a-f0-9]{64}\z/', $package['archive_sha256'])
            || !is_array($package['files']) || count($package['files']) < 1 || count($package['files']) > 1000) {
            throw new RuntimeException('package_invalid');
        }
    }

    public function inspect()
    {
        if (!class_exists('ZipArchive')) { throw new RuntimeException('zip_required'); }
        $file = $this->root . '/' . $this->package['archive'];
        $temporary = null;
        if ($this->embedded !== null) {
            if (!is_string($this->embedded) || strlen($this->embedded) > 8388608
                || !hash_equals($this->package['archive_sha256'], hash('sha256', $this->embedded))) { throw new RuntimeException('zip_changed'); }
            $temporary = tmpfile();
            if (!$temporary) { throw new RuntimeException('private_temp_required'); }
            $file = stream_get_meta_data($temporary)['uri'];
            $publicRoots = [$this->root];
            if (!empty($_SERVER['DOCUMENT_ROOT']) && realpath($_SERVER['DOCUMENT_ROOT'])) { $publicRoots[] = realpath($_SERVER['DOCUMENT_ROOT']); }
            foreach ($publicRoots as $publicRoot) {
                if (strpos(realpath($file), rtrim($publicRoot, '/') . '/') === 0) {
                    fclose($temporary); throw new RuntimeException('private_temp_required');
                }
            }
            if (fwrite($temporary, $this->embedded) !== strlen($this->embedded)) { fclose($temporary); throw new RuntimeException('paths_failed'); }
        } else {
            if (is_link($file) || !is_file($file) || !is_readable($file)) { throw new RuntimeException('zip_missing'); }
            if (filesize($file) > 8388608 || !hash_equals($this->package['archive_sha256'], hash_file('sha256', $file))) { throw new RuntimeException('zip_changed'); }
        }
        $zip = new ZipArchive();
        if ($zip->open($file) !== true) { if ($temporary) { fclose($temporary); } throw new RuntimeException('package_invalid'); }
        $contents = [];
        $expected = [];
        $total = 0;
        try {
            foreach ($this->package['files'] as $entry) {
                if (!isset($entry['path'], $entry['bytes'], $entry['sha256']) || !is_string($entry['path'])
                    || strpos($entry['path'], self::PREFIX) !== 0 || !is_int($entry['bytes'])
                    || $entry['bytes'] < 0 || $entry['bytes'] > 10485760 || !is_string($entry['sha256'])
                    || !preg_match('/\A[a-f0-9]{64}\z/', $entry['sha256'])) { throw new RuntimeException('package_invalid'); }
                $relative = substr($entry['path'], strlen(self::PREFIX));
                if (!preg_match('/\A(?:[a-zA-Z0-9_-][a-zA-Z0-9_.-]*\/)*[a-zA-Z0-9_-][a-zA-Z0-9_.-]*\z/', $relative)
                    || isset($expected[strtolower($entry['path'])])) { throw new RuntimeException('package_invalid'); }
                $expected[strtolower($entry['path'])] = $entry;
                $total += $entry['bytes'];
            }
            if ($total > 16777216 || $zip->numFiles !== count($expected)) { throw new RuntimeException('package_invalid'); }
            foreach (range(0, $zip->numFiles - 1) as $index) {
                $info = $zip->statIndex($index);
                $name = $info['name'];
                $entry = $expected[strtolower($name)] ?? null;
                $zip->getExternalAttributesIndex($index, $system, $attributes);
                if (!$entry || $entry['path'] !== $name || isset($contents[$name])
                    || (($attributes >> 16) & 0170000) === 0120000 || $info['size'] !== $entry['bytes']) {
                    throw new RuntimeException('package_invalid');
                }
                $data = $zip->getFromIndex($index, $entry['bytes'] + 1);
                if (!is_string($data) || strlen($data) !== $entry['bytes']
                    || !hash_equals($entry['sha256'], hash('sha256', $data))) { throw new RuntimeException('package_invalid'); }
                $contents[$name] = $data;
            }
        } finally { $zip->close(); if ($temporary) { fclose($temporary); } }
        return $contents;
    }

    public function preflight($script)
    {
        if ($script !== $this->root . '/' . ($this->package['installer'] ?? 'c1zz-ai-install.php') || is_link($script) || !is_file($script)
            || !is_writable($this->root) || !is_readable($this->root)) { throw new RuntimeException('cleanup_permissions'); }
        return $this->preflightUpdate();
    }

    /** Native admin updates need no executable entry file in the shop root. */
    public function preflightUpdate()
    {
        foreach (['cache', 'cache/smarty', 'GXModules', 'GXModules/c1zz', rtrim(self::PREFIX,'/'),rtrim(self::LEGACY_PREFIX,'/')] as $relative) {
            $path = $this->root . '/' . $relative;
            if (is_link($path) || (file_exists($path) && (!is_dir($path) || !is_writable($path)))) { throw new RuntimeException('paths_failed'); }
        }
        if (!is_dir($this->root . '/cache') || !is_dir($this->root . '/GXModules')) { throw new RuntimeException('paths_failed'); }
        if (is_dir($this->root.'/'.self::PREFIX) && is_dir($this->root.'/'.self::LEGACY_PREFIX)) { throw new RuntimeException('legacy_module_conflict'); }
        return count($this->inspect());
    }

    public function apply()
    {
        $cache = $this->root . '/cache';
        $gx = $this->root . '/GXModules';
        $vendor = $gx . '/c1zz';
        $target = $this->root . '/' . rtrim(self::PREFIX,'/');
        $legacy = $this->root . '/' . rtrim(self::LEGACY_PREFIX,'/');
        if (file_exists($legacy) && file_exists($target)) { throw new RuntimeException('legacy_module_conflict'); }
        $previousTarget = is_dir($legacy) ? $legacy : $target;
        $previousPrefix = $previousTarget === $legacy ? self::LEGACY_PREFIX : self::PREFIX;
        foreach ([$cache, $gx, $vendor, $target, $legacy] as $path) {
            if (is_link($path) || (file_exists($path) && !is_dir($path))) { throw new RuntimeException('path_invalid'); }
        }
        if (!is_dir($cache) || !is_writable($cache) || !is_dir($gx)
            || !is_writable(is_dir($vendor) ? $vendor : $gx)) { throw new RuntimeException('paths_failed'); }
        $lockPath = $cache . '/c1zz-ai-package.lock';
        if (is_link($lockPath)) { throw new RuntimeException('path_invalid'); }
        $lock = fopen($lockPath, 'c');
        if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) { if ($lock) { fclose($lock); } throw new RuntimeException('package_busy'); }
        chmod($lockPath, 0600);
        $stage = null;
        $movedOld = false;
        $published = false;
        $preserve = false;
        try {
            $contents = $this->inspect();
            if (is_dir($previousTarget)) {
                $allowed = array_fill_keys(array_map(function ($name) { return substr($name, strlen(self::PREFIX)); }, array_keys($contents)), true);
                $oldManifest = $previousTarget . '/package-manifest.json';
                if ($previousTarget === $legacy && (!is_file($oldManifest) || is_link($oldManifest))) { throw new RuntimeException('unknown_files'); }
                if (is_file($oldManifest) && !is_link($oldManifest) && filesize($oldManifest) <= 1048576) {
                    $old = json_decode(file_get_contents($oldManifest), true);
                    if ($previousTarget === $legacy && !is_array($old['files'] ?? null)) { throw new RuntimeException('unknown_files'); }
                    foreach (is_array($old['files'] ?? null) ? $old['files'] : [] as $entry) {
                        if (is_string($entry['path'] ?? null) && strpos($entry['path'], $previousPrefix) === 0) {
                            $allowed[substr($entry['path'], strlen($previousPrefix))] = true;
                        }
                    }
                }
                foreach (new RecursiveIteratorIterator(new RecursiveDirectoryIterator($previousTarget, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST) as $file) {
                    if ($file->isLink()) { throw new RuntimeException('path_invalid'); }
                    if (!$file->isDir() && !isset($allowed[substr($file->getPathname(), strlen($previousTarget) + 1)])) {
                        throw new RuntimeException('unknown_files');
                    }
                }
            }
            if (!is_dir($vendor) && !mkdir($vendor, 0755)) { throw new RuntimeException('paths_failed'); }
            if (stat($cache)['dev'] !== stat($vendor)['dev']) { throw new RuntimeException('filesystem_mismatch'); }
            $stage = $cache . '/c1zz-ai-package-' . bin2hex(random_bytes(12));
            if (!mkdir($stage, 0700)) { throw new RuntimeException('paths_failed'); }
            file_put_contents($stage . '/.htaccess', "Require all denied\nDeny from all\n");
            mkdir($stage . '/module', 0755);
            foreach ($contents as $name => $data) {
                $path = $stage . '/module/' . substr($name, strlen(self::PREFIX));
                if (!is_dir(dirname($path)) && !mkdir(dirname($path), 0755, true)) { throw new RuntimeException('paths_failed'); }
                if (file_put_contents($path, $data, LOCK_EX) !== strlen($data)) { throw new RuntimeException('paths_failed'); }
                chmod($path, 0644);
            }
            if (is_dir($previousTarget)) {
                if (!rename($previousTarget, $stage . '/previous')) { throw new RuntimeException('paths_failed'); }
                $movedOld = true;
            }
            if (!rename($stage . '/module', $target)) { throw new RuntimeException('paths_failed'); }
            $published = true;
            foreach ($contents as $name => $data) {
                if (!hash_equals(hash('sha256', $data), hash_file('sha256', $this->root . '/' . $name))) {
                    throw new RuntimeException('package_invalid');
                }
                if (substr($name, -4) === '.php' && function_exists('opcache_invalidate')) {
                    opcache_invalidate($this->root . '/' . $name, true);
                }
            }
            return count($contents);
        } catch (Throwable $error) {
            if ($published && !rename($target, $stage . '/failed')) { $preserve = true; }
            if ($movedOld && !rename($stage . '/previous', $previousTarget)) { $preserve = true; }
            if ($preserve) { throw new RuntimeException('restore_failed'); }
            throw $error;
        } finally {
            if ($stage !== null && !$preserve) { self::removeDirectory($stage); }
            flock($lock, LOCK_UN); fclose($lock);
        }
    }

    public function cleanupUploads($script, $completed)
    {
        if ($completed !== true || $script !== $this->root . '/' . ($this->package['installer'] ?? 'c1zz-ai-install.php') || is_link($script) || !is_file($script)) {
            throw new RuntimeException('request_invalid');
        }
        $zip = $this->root . '/' . $this->package['archive'];
        if (is_link($zip) || (is_file($zip) && !hash_equals($this->package['archive_sha256'], hash_file('sha256', $zip)))) {
            throw new RuntimeException('zip_changed');
        }
        if (is_file($zip) && !unlink($zip)) { throw new RuntimeException('cleanup_failed'); }
        if (!unlink($script)) { throw new RuntimeException('cleanup_failed'); }
    }

    private static function removeDirectory($path)
    {
        $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
        foreach ($files as $file) { $file->isDir() && !$file->isLink() ? rmdir($file->getPathname()) : unlink($file->getPathname()); }
        rmdir($path);
    }
}

/** Keep native authentication, but route installer authentication to the admin login. */
final class C1zzAiInstallerLogin
{
    public static function register($base, $entry)
    {
        if (($_SERVER['REQUEST_METHOD'] ?? '') === 'GET' && ($_GET['admin_login'] ?? '') === '1') {
            self::render($base, $entry);
            exit;
        }
        header_register_callback(function () use ($base, $entry) {
            // Native application_top may exit while redirecting an unauthenticated user.
            // Inspect only that response's login destination, without suppressing its checks.
            foreach (headers_list() as $header) {
                if (stripos($header, 'Location:') !== 0) { continue; }
                $target = self::target(trim(substr($header, 9)), defined('DIR_WS_CATALOG') ? DIR_WS_CATALOG : $base);
                if ($target !== null) {
                    header('Cache-Control: no-store, private, max-age=0');
                    if (self::probeRequested()) {
                        header_remove('Location');
                        http_response_code(401);
                    } else {
                        header('Location: ' . $entry . '?admin_login=1', true, 303);
                    }
                }
            }
        });
    }

    public static function probeRequested()
    {
        return ($_SERVER['REQUEST_METHOD'] ?? '') === 'GET' && ($_GET['admin_probe'] ?? '') === '1';
    }

    /** Call only after native admin status AND Module Center write permission checks. */
    public static function authenticated()
    {
        if (self::probeRequested()) {
            header('Cache-Control: no-store, private, max-age=0');
            http_response_code(204);
            exit;
        }
    }

    private static function render($base, $entry)
    {
        header('Content-Type: text/html; charset=utf-8');
        header('Cache-Control: no-store, private, max-age=0');
        header('X-Frame-Options: DENY');
        header('X-Content-Type-Options: nosniff');
        header('Referrer-Policy: same-origin');
        $escape = function ($value) { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); };
        $login = rtrim($base, '/') . '/login_admin.php';
        $encodedEntry = json_encode($entry, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
        ?>
