    public static function target($location, $catalog)
    {
        $path = parse_url($location, PHP_URL_PATH);
        $base = rtrim($catalog, '/');
        if (!is_string($path) || !in_array($path, [$base . '/login.php', $base . '/admin/../login.php'], true)) {
            return null;
        }
        // A local configured path; never forward return URLs, credentials or POST parameters.
        return $base . '/login_admin.php';
    }
}

